function equalToDescendants(root) {
  // Collect every node, then add up each node's descendants with a separate walk.
  const all = [];
  const pending = [root];
  while (pending.length) {
    const node = pending.pop();
    if (!node) continue;
    all.push(node);
    pending.push(node.left, node.right);
  }
  let matches = 0;
  for (const top of all) {
    let total = 0;
    const walk = [top.left, top.right];
    while (walk.length) {
      const node = walk.pop();
      if (!node) continue;
      total += node.val;
      walk.push(node.left, node.right);
    }
    if (total === top.val) matches++;
  }
  return matches;
}

