function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 80) : 1 + Math.floor(rand() * 10);
  const narrow = rand() < 0.6;
  const value = () => narrow ? Math.floor(rand() * (large ? 20 : 6)) : Math.floor(rand() * 100001);
  // Shape: an optional long downward chain, then random attachment to free child slots.
  const chain = large ? (rand() < 0.4 ? 100 + Math.floor(rand() * 400) : 1) : (rand() < 0.25 ? n : 1);
  const nodes = [{ val: 0, left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: 0, left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: 0, left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Children always have larger indices, so filling values from the back sees descendants first.
  // Many nodes copy their descendant sum so that matches are common.
  const below = new Array(n).fill(0);
  const share = rand() * 0.6;
  for (let i = n - 1; i >= 0; i--) {
    const node = nodes[i];
    for (const child of [node.left, node.right]) if (child !== null) below[i] += below[child] + nodes[child].val;
    node.val = rand() < share && below[i] <= 100000 ? below[i] : value();
  }
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
